"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["36162"],{27031(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.natureza_invalida","status":422,"titulo":"Natureza do tipo de conceito inv\xe1lida"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.natureza_invalida","requisitos":[],"oQueAconteceu":["O campo `natureza` enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) n\xe3o \xe9 `NUMERICO` nem `POR_OPCOES`. A compara\xe7\xe3o \xe9 exata: `Numerico` ou `numerico` s\xe3o recusados. O campo ausente, nulo ou vazio tamb\xe9m cai aqui, porque o corpo o declara como texto anul\xe1vel de prop\xf3sito, para que a aus\xeancia chegue \xe0 regra do dom\xednio e responda 422 em vez de uma recusa gen\xe9rica de 400.","A natureza decide quais par\xe2metros o tipo exige: o num\xe9rico, a escala em `numerico`; o categ\xf3rico, a lista em `valores`. Com a natureza inv\xe1lida, nenhum dos dois \xe9 conferido, e s\xf3 as demais recusas do corpo (como o nome) saem junto.","A recusa vem na lista `errors` da resposta, com `field` igual a `natureza`. Nada \xe9 gravado. Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Envie `natureza` como `NUMERICO` ou `POR_OPCOES`, junto com os par\xe2metros da natureza escolhida, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);